<?php
declare(strict_types=1);
namespace Kios\MerchantOperations;

final class IntegratedSetupView
{
 private static function h(mixed $s):string{return htmlspecialchars((string)$s,ENT_QUOTES,'UTF-8');}
 private static function hidden(string $k,mixed $v):string{return '<input type="hidden" name="'.$k.'" value="'.self::h($v).'">';}
 private static function link(string $q,string $text,string $class=''):string{return '<a class="'.self::h($class).'" href="/merchant.php?'.self::h($q).'">'.self::h($text).'</a>';}
 private static function shell(string $title,string $content,string $csrf,bool $platform=false):string
 {
  return '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'.self::h($title).' · KIOS</title><link rel="stylesheet" href="/assets/platform-admin.css"><link rel="stylesheet" href="/assets/integrated-setup.css"><script src="/assets/integrated-setup.js" defer></script></head><body class="platform-console"><a class="is-skip" href="#setup-main">Skip to setup</a><aside class="pa-sidebar"><a class="pa-logo" href="/merchant.php">KIOS</a><p>CONNECTED WORKSPACES</p><nav aria-label="Setup navigation">'.self::link('','My dashboard').($platform?self::link('platform=merchants','Platform merchant directory'):'').'</nav><form method="post">'.self::hidden('_csrf',$csrf).self::hidden('action','logout').'<button>Sign out</button></form><p class="pa-safety">Private synthetic demonstration<br>Ordering CLOSED<br>Payments &amp; printing DISABLED</p></aside><main id="setup-main" data-integrated-setup><header class="pa-header"><div><p class="pa-eyebrow">KIOS / GUIDED SETUP</p><h1>'.self::h($title).'</h1></div><span class="pa-private">PRIVATE DEMO</span></header><p class="pa-banner">Configure safely. Review does not open customer ordering or authorize commercial use.</p>'.$content.'<footer class="pa-footer">Server-authorized scope · Synthetic data only · Audit timestamps UTC</footer></main></body></html>';
 }
 public static function directory(array $d,string $csrf):string
 {
  $m=$d['merchant'];$platform=$d['platform'];$scope='merchant='.rawurlencode($m).($platform?'&platform_setup=1':'');
  $x='<section class="pa-panel"><p class="pa-eyebrow">SELECT MERCHANT → CHOOSE OUTLET → CONFIGURE → REVIEW → OPEN DASHBOARD</p><h2>'.self::h($d['name']).'</h2><p>Each outlet has independent menu, kitchen, inventory, seating and branding. Subscription capacity and existing permissions still apply.</p><div class="is-grid">';
  foreach($d['outlets']as$o){$q=$scope.'&outlet='.rawurlencode($o['outlet_id']);$x.='<article class="is-card"><span class="is-tag">SHOP CLOSED</span><h3>'.self::h($o['name']).'</h3><p class="is-ref">'.self::h($o['outlet_id']).'</p>'.self::link('outlet_wizard=1&'.$q,'Configure & review','pa-button').self::link('outlet_home=1&'.$q,'Open scoped dashboard','is-text-link').'</article>';}
  $x.='</div></section>';
  if($platform){$n=$d['native']['merchant'];$x.='<section class="pa-panel"><h2>1. Create another closed outlet</h2><p>Uses the native provisioning engine. Retry of the same request returns its existing receipt; stale revisions and duplicate names are rejected.</p><form method="post" data-integrated-form>'.self::hidden('_csrf',$csrf).self::hidden('action','platform-admin').self::hidden('op','outlet-create').self::hidden('merchant',$m).self::hidden('expected',$n['admin_version']).self::hidden('request',bin2hex(random_bytes(16))).'<div class="pa-two"><label>Outlet name<input name="data[name]" maxlength="160" required></label><label>Scheduled opening<input name="data[opening]" type="time" value="08:00" required></label><label>Scheduled closing<input name="data[closing]" type="time" value="22:00" required></label></div><label>Reason<input name="reason" maxlength="240" required></label><label class="is-check"><input type="checkbox" name="confirm" value="yes" required>I confirm this synthetic outlet creation.</label><button>Create closed outlet</button><p role="status" data-save-status></p></form></section>';}
  else $x.='<section class="pa-panel"><h2>Need another outlet?</h2><p>An authorized platform administrator creates the independent native outlet and assigns access. No new credentials or roles are granted by this selector.</p></section>';
  return self::shell('My outlets',$x,$csrf,$platform);
 }
 public static function render(array $d,string $csrf,string $mode='assistant',string $error='',bool $saved=false):string
 {
  $m=$d['merchant'];$o=$d['outlet'];$platform=$d['platform'];$scope='merchant='.rawurlencode($m).'&outlet='.rawurlencode($o).($platform?'&platform_setup=1':'');$cfg=$d['configuration'];
  $x='<section class="pa-panel is-identity" data-merchant="'.self::h($m).'" data-outlet="'.self::h($o).'"><div><p class="pa-eyebrow">'.self::h($d['mapping']['merchant_name']).'</p><h2>'.self::h($d['mapping']['name']).'</h2><p>Scheduled hours '.self::h($d['mapping']['opening_time']).'–'.self::h($d['mapping']['closing_time']).' · SHOP CLOSED</p></div><label>Selected outlet<select data-outlet-select aria-label="Selected outlet">';
  foreach($d['outlets']as$out){$q='outlet_wizard=1&merchant='.rawurlencode($m).'&outlet='.rawurlencode($out['outlet_id']).($platform?'&platform_setup=1':'');$x.='<option value="'.self::h('/merchant.php?'.$q).'"'.($out['outlet_id']===$o?' selected':'').'>'.self::h($out['name']).'</option>';}$x.='</select></label></section><nav class="is-tabs" aria-label="Outlet steps">'.self::link('outlet_directory=1&merchant='.$m.($platform?'&platform_setup=1':''),'1 · Select / create outlet').self::link('outlet_wizard=1&'.$scope,'2 · Configure & review').self::link('assistant=1&'.$scope,'3 · Setup assistant').self::link('outlet_home=1&'.$scope,'4 · Outlet dashboard').'</nav>';
  if($error!=='')$x.='<section class="pa-error" role="alert"><h2>Configuration not saved</h2><p>'.self::h($error).'</p><p>Reload current settings before retrying; no partial changes were committed.</p></section>';
  if($saved)$x.='<p class="pa-success" role="status">Outlet configuration saved and audited.</p>';
  if($platform){$n=$d['native'];$x.='<section class="pa-panel"><h2>Integrated merchant journey</h2><ol class="is-progress"><li>Create merchant: native receipt recorded</li><li>Administrator: '.self::h($n['onboarding']['status']??'Review native owner').'</li><li>Subscription: '.self::h($d['lifecycle']['state']??'UNASSIGNED').'</li><li>Outlet review: '.($cfg&&$cfg['reviewed']?'Reviewed':'Pending').'</li><li>Private access: '.self::h($n['merchant']['admin_status']??$n['merchant']['status']??'Review native access').'</li></ol><div class="is-links">'.self::link('platform=detail&merchant='.$m,'Owner credentials, outlet names & role assignments','pa-button').self::link('plans=1#lifecycle','Assign subscription / lifecycle','pa-button').'</div><p>The original owner signs in normally to save business details and configure products, kitchen and staff. Platform administration does not impersonate the owner. Activate private access through the existing merchant controls only after subscription and configuration review.</p></section>';}
  $editable=$platform||$d['owner'];
  if($mode==='wizard'&&$editable){$v=(string)($cfg['version']??0);$form=function(string $op)use($csrf,$m,$o,$v,$platform):string{return '<form method="post" data-integrated-form>'.self::hidden('_csrf',$csrf).self::hidden('action','integration-'.$op).self::hidden('merchant',$m).self::hidden('outlet',$o).self::hidden('expected',$v).self::hidden('request',bin2hex(random_bytes(16))).self::hidden('platform_setup',$platform?'1':'0');};
   $x.='<section class="pa-panel"><h2>2. Outlet identity & operational modules</h2><p>Saving preferences can restrict licensed features. It never grants a subscription or role. Menu categories and preparation routes remain independent.</p>'.$form('save').'<div class="pa-two"><label>Outlet address<textarea name="profile[address]" maxlength="500" required>'.self::h($d['profile']['address']??'').'</textarea></label><label>Outlet contact email or phone<input name="profile[contact]" maxlength="120" value="'.self::h($d['profile']['contact']??'').'" required></label></div><fieldset><legend>Licensed modules for this outlet</legend><div class="is-modules">';
   foreach(Entitlements::FEATURES as$f){$licensed=in_array($f,$d['licensed'],true);$x.='<label class="is-check"><input type="checkbox" name="modules[]" value="'.self::h($f).'"'.(in_array($f,$d['selected'],true)?' checked':'').(!$licensed?' disabled':'').'>'.self::h(ucwords(str_replace('_',' ',$f))).(!$licensed?' · Not in current subscription':'').'</label>';}
   $x.='</div><p>Dependencies: POS needs menu, kitchen and floor. Reservations need floor. Recipes need inventory and menu. Branding needs menu.</p></fieldset><label>Reason<input name="reason" maxlength="240" required></label><label class="is-check"><input type="checkbox" name="confirm" value="yes" required>I confirm this authorized synthetic configuration.</label><button>Save outlet settings</button><p role="status" data-save-status></p></form></section><section class="pa-panel"><h2>3. Review current configuration</h2><p>'.($cfg&&$cfg['reviewed']?'Current revision reviewed.':'Pending review. New internal POS work requires review.').'</p>'.$form('review').'<p>Review the saved contact, address, module choices and native administrator assignments. Subsequent edits require a fresh review.</p><label>Review remarks<input name="reason" maxlength="240" required></label><label class="is-check"><input type="checkbox" name="confirm" value="yes" required>I reviewed the saved outlet configuration.</label><button'.(!$cfg||(int)$cfg['version']===0?' disabled':'').'>Confirm outlet review</button><p role="status" data-save-status></p></form></section>';
  }
  $ready=count(array_filter($d['cards'],fn($c)=>$c['ready']));$x.='<section class="pa-panel"><div class="pa-heading"><h2>'.($mode==='home'?'Outlet workspaces':'Setup assistant').'</h2><span class="is-tag">'.$ready.' / '.count($d['cards']).' READY</span></div><p>Readiness reflects saved records and current authorization. Unconfigured modules are not marked ready. Each tool uses this selected outlet.</p><div class="is-grid">';
  foreach($d['cards']as$c){$status=!$c['enabled']?'Unavailable':($c['ready']?'Ready':'Setup required');$x.='<article class="is-card" data-setup-card="'.self::h($c['id']).'"><span class="is-tag" data-ready="'.($c['ready']?'yes':'no').'">'.$status.'</span><h3>'.self::h($c['label']).'</h3><p>'.self::h($c['detail']).'</p>';if($c['canOpen'])$x.=self::link($c['url'],'Open workspace','pa-button');elseif($platform)$x.='<p>Original owner configures this workspace.</p>';elseif(!$c['enabled'])$x.='<p>Review subscription and selected outlet modules.</p>';else$x.='<p>Original merchant owner manages configuration.</p>';$x.='</article>';}$x.='</div></section>';
  $x.='<section class="pa-panel"><h2>Configuration history</h2><p>Outlet configuration history is separate from existing provisioning, staff and operational audits.</p><div class="is-history">';foreach($d['history']as$h)$x.='<article><strong>Revision '.(int)$h['version'].' · '.self::h($h['operation']).'</strong><p>'.self::h($h['reason']).'</p><small>'.self::h(gmdate('Y-m-d H:i:s',(int)$h['created_epoch'])).' UTC · '.self::h($h['actor_id']).'</small></article>';if(!$d['history'])$x.='<p>No guided configuration changes yet. Existing native records remain unchanged.</p>';$x.='</div></section>';
  return self::shell($mode==='wizard'?'Configure outlet':($mode==='home'?'Outlet dashboard':'Merchant setup assistant'),$x,$csrf,$platform);
 }
}
